// lrapr-t006/u3-ingest-memos — step 1: probe repo, tag ref, tag object, commit, recursive tree.
// Network: consented acquisition only. GET, identity encoding, no credentials, no redirects, no retries.
// Run from the repository root with VERSIONLESS_NETWORK_MODE=consented.
import fs from 'node:fs';
import https from 'node:https';
import crypto from 'node:crypto';

const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
const REPO = 'usememos/memos';
const TAG = 'v0.1.3';
const EXPECTED_COMMIT = '565fe0cc567c02deb59fc04830df707ea7476d52';
const D = 'evidence/ingests/react-memos-v0-1-3';
const CACHE = '.versionless/cache/react-memos-v0-1-3-source';

if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented') {
  throw new Error('refusing to run: VERSIONLESS_NETWORK_MODE is not "consented"');
}

fs.mkdirSync(D, { recursive: true });
fs.mkdirSync(`${CACHE}/probe`, { recursive: true });

const sha256 = (b) => crypto.createHash('sha256').update(b).digest('hex');
const ledger = [];

function get(url) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    https
      .get(
        {
          hostname: u.hostname,
          path: u.pathname + u.search,
          headers: {
            'user-agent': 'versionless-legacy-corpus',
            accept: 'application/vnd.github+json',
            'accept-encoding': 'identity',
          },
        },
        (res) => {
          const chunks = [];
          res.on('data', (c) => chunks.push(c));
          res.on('end', () =>
            resolve({ status: res.statusCode, body: Buffer.concat(chunks) }),
          );
        },
      )
      .on('error', reject);
  });
}

async function probe(phase, url) {
  const r = await get(url);
  ledger.push({
    at: new Date().toISOString(),
    phase,
    method: 'GET',
    url,
    status: r.status,
    bytes: r.body.length,
    sha256: sha256(r.body),
  });
  if (r.status !== 200) throw new Error(`non-200 for ${url}: ${r.status}`);
  return r;
}

const out = {};

const repoRes = await probe('admission-gate-probe', `https://api.github.com/repos/${REPO}`);
const repo = JSON.parse(repoRes.body.toString('utf8'));
out.repository = {
  id: repo.id,
  fullName: repo.full_name,
  private: repo.private,
  archived: repo.archived,
  disabled: repo.disabled,
  defaultBranch: repo.default_branch,
  license: repo.license ? { key: repo.license.key, spdxId: repo.license.spdx_id } : null,
  responseBytes: repoRes.body.length,
  responseSha256: sha256(repoRes.body),
};

const refRes = await probe(
  'admission-gate-probe',
  `https://api.github.com/repos/${REPO}/git/ref/tags/${TAG}`,
);
const ref = JSON.parse(refRes.body.toString('utf8'));
out.ref = { ref: ref.ref, objectType: ref.object.type, objectSha: ref.object.sha };

let commitSha;
let tagObject = null;
if (ref.object.type === 'tag') {
  const tagRes = await probe(
    'admission-gate-probe',
    `https://api.github.com/repos/${REPO}/git/tags/${ref.object.sha}`,
  );
  const t = JSON.parse(tagRes.body.toString('utf8'));
  tagObject = {
    sha: t.sha,
    tag: t.tag,
    message: t.message,
    taggerDate: t.tagger ? t.tagger.date : null,
    verified: t.verification ? t.verification.verified : null,
    reason: t.verification ? t.verification.reason : null,
    targetSha: t.object.sha,
    targetType: t.object.type,
  };
  commitSha = t.object.sha;
} else {
  commitSha = ref.object.sha;
}
out.tagObject = tagObject;
out.tagKind = ref.object.type === 'tag' ? 'annotated' : 'lightweight';

if (commitSha !== EXPECTED_COMMIT) {
  throw new Error(`commit sha mismatch: wire ${commitSha} != expected ${EXPECTED_COMMIT}`);
}

const commitRes = await probe(
  'admission-gate-probe',
  `https://api.github.com/repos/${REPO}/git/commits/${commitSha}`,
);
const commit = JSON.parse(commitRes.body.toString('utf8'));
out.commit = {
  sha: commit.sha,
  authorDate: commit.author.date,
  committerDate: commit.committer.date,
  message: commit.message,
  treeSha: commit.tree.sha,
  parents: commit.parents.map((p) => p.sha),
  verified: commit.verification ? commit.verification.verified : null,
  reason: commit.verification ? commit.verification.reason : null,
};

const treeRes = await probe(
  'admission-gate-probe',
  `https://api.github.com/repos/${REPO}/git/trees/${commit.tree.sha}?recursive=1`,
);
const tree = JSON.parse(treeRes.body.toString('utf8'));
fs.writeFileSync(`${CACHE}/probe/tree.json`, treeRes.body);

const counts = { blob: 0, tree: 0, commit: 0, other: 0, symlink: 0, executable: 0 };
for (const e of tree.tree) {
  if (e.type === 'blob') {
    counts.blob += 1;
    if (e.mode === '120000') counts.symlink += 1;
    if (e.mode === '100755') counts.executable += 1;
  } else if (e.type === 'tree') counts.tree += 1;
  else if (e.type === 'commit') counts.commit += 1;
  else counts.other += 1;
}
out.tree = {
  sha: tree.sha,
  truncated: tree.truncated,
  entries: tree.tree.length,
  blobs: counts.blob,
  directories: counts.tree,
  gitlinks: counts.commit,
  symlinks: counts.symlink,
  executableBlobs: counts.executable,
  responseBytes: treeRes.body.length,
  responseSha256: sha256(treeRes.body),
};

const byPath = new Map(tree.tree.map((e) => [e.path, e]));
const pick = (p) => {
  const e = byPath.get(p);
  return e ? { path: p, sha: e.sha, mode: e.mode, size: e.size ?? null } : null;
};
out.keyPaths = {
  LICENSE: pick('LICENSE'),
  'web/package.json': pick('web/package.json'),
  'web/yarn.lock': pick('web/yarn.lock'),
  'web/vite.config.ts': pick('web/vite.config.ts'),
  '.gitattributes': pick('.gitattributes'),
  'go.mod': pick('go.mod'),
};
out.lockfilesInTree = tree.tree
  .filter((e) =>
    /(^|\/)(package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml)$/.test(e.path),
  )
  .map((e) => ({ path: e.path, sha: e.sha, size: e.size ?? null }));
out.licenceLikeFilesInTree = tree.tree
  .filter((e) => e.type === 'blob' && /(^|\/)(LICEN[SC]E|COPYING|NOTICE)([.-][^/]*)?$/i.test(e.path))
  .map((e) => ({ path: e.path, sha: e.sha, size: e.size ?? null }));
out.gitattributesInTree = tree.tree
  .filter((e) => /(^|\/)\.gitattributes$/.test(e.path))
  .map((e) => e.path);
out.webSubtree = {
  totalEntries: tree.tree.filter((e) => e.path === 'web' || e.path.startsWith('web/')).length,
  blobs: tree.tree.filter((e) => e.type === 'blob' && e.path.startsWith('web/')).length,
  srcBlobs: tree.tree.filter((e) => e.type === 'blob' && e.path.startsWith('web/src/')).length,
};

fs.appendFileSync(
  `${D}/probe-ledger.ndjson`,
  ledger.map((x) => JSON.stringify(x)).join('\n') + '\n',
);
fs.appendFileSync(
  `${D}/transcript.ndjson`,
  JSON.stringify({
    at: new Date().toISOString(),
    step: 'probe-repo-tag-commit-tree',
    runner: 'node evidence/ingests/react-memos-v0-1-3/drivers/01-probe.mjs',
    consentId: CONSENT,
    networkMode: process.env.VERSIONLESS_NETWORK_MODE,
    nodeVersion: process.version,
    requests: ledger.length,
    expectedCommitShaConfirmedFromWire: commitSha === EXPECTED_COMMIT,
  }) + '\n',
);
fs.writeFileSync(`${D}/probe-tree.json`, JSON.stringify(out, null, 2) + '\n');
console.log(JSON.stringify(out, null, 2));

