// lrapr-t006/u3-ingest-memos — step 2: fetch the source archive twice, prove the two streams are
// byte-identical, extract one, and reconcile every extracted regular file blob-for-blob against the
// recursive git tree at the pinned revision. Also scans every blob for a git-lfs pointer header.
// Run from the repository root with VERSIONLESS_NETWORK_MODE=consented.
import fs from 'node:fs';
import path from 'node:path';
import https from 'node:https';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
const REPO = 'usememos/memos';
const COMMIT = '565fe0cc567c02deb59fc04830df707ea7476d52';
const D = 'evidence/ingests/react-memos-v0-1-3';
const CACHE = '.versionless/cache/react-memos-v0-1-3-source';
const MAX_ARCHIVE_BYTES = 134217728;

if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented') {
  throw new Error('refusing to run: VERSIONLESS_NETWORK_MODE is not "consented"');
}

fs.mkdirSync(`${CACHE}/archive`, { recursive: true });
fs.mkdirSync(`${CACHE}/verify`, { recursive: true });

const sha256 = (b) => crypto.createHash('sha256').update(b).digest('hex');
const gitBlobSha = (b) =>
  crypto
    .createHash('sha1')
    .update(Buffer.concat([Buffer.from(`blob ${b.length}\0`), b]))
    .digest('hex');

const ledger = [];
const url = `https://codeload.github.com/${REPO}/tar.gz/${COMMIT}`;

function fetchArchive(stream) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    https
      .get(
        {
          hostname: u.hostname,
          path: u.pathname,
