let descriptors = 0;
let withResolved = 0;
let withIntegrity = 0;
const hosts = {};
const algos = {};
const versions = [];
const noResolved = [];
const noIntegrity = [];

for (const b of blocks) {
  const lines = b.split('\n');
  const header = lines[0];
  if (!header.endsWith(':')) continue;
  entries += 1;
  descriptors += header.slice(0, -1).split(/,\s*/).length;
  const ver = /^\s+version\s+"([^"]+)"/m.exec(b);
  const res = /^\s+resolved\s+"([^"]+)"/m.exec(b);
  const integ = /^\s+integrity\s+(\S+)/m.exec(b);
  const name = header.slice(0, -1).split(/,\s*/)[0].replace(/^"|"$/g, '').replace(/@[^@]*$/, '');
  versions.push({ name, version: ver ? ver[1] : null });
  if (res) {
    withResolved += 1;
    const h = new URL(res[1]).hostname;
    hosts[h] = (hosts[h] || 0) + 1;
  } else noResolved.push(name);
  if (integ) {
    withIntegrity += 1;
    const a = integ[1].split('-')[0];
    algos[a] = (algos[a] || 0) + 1;
  } else noIntegrity.push(name);
}

